void hanoi(int n, char from, char via, char to) {
    if (n == 0) return;
    hanoi(n - 1, from, to, via);                  /* n-1 個先移到輔助柱 */
    printf("disk %d: %c -> %c\n", n, from, to);   /* 最大的移到目的柱 */
    hanoi(n - 1, via, from, to);                  /* n-1 個移到目的柱 */
}
